    h,w=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==0 or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); cells=[]
            while q:
                x,y=q.pop(); cells.append((x,y))
                for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
                    if 0<=a<h and 0<=b<w and grid[a][b]==color and (a,b) not in seen:
                        seen.add((a,b)); q.append((a,b))
            comps.append((color,cells))
    out=[[0]*w for _ in range(h)]
    # Objects are paired by color. Each object from the upper half transfers to
    # the lower half, and objects from the lower half transfer to the upper half.
    # Demonstration shows the larger repeated shapes resolving into color rows.
    cols=sorted(set(col for col,cells in comps))
    for color in cols:
        cells=[(r,c) for col,cs in comps if col==color for r,c in cs]
        if not cells: continue
        # Transfer all colored cells to a row in the opposite vertical half,
        # keeping their horizontal coordinates; preserve a contiguous row encoding.
        upper=[(r,c) for r,c in cells if r<h//2]
        lower=[(r,c) for r,c in cells if r>=h//2]
        if upper:
            coords=sorted(c for r,c in upper)
            rr=h//2+max(0, (len(coords)-1)//2)
            for c in coords:
                if rr<h: out[rr][c]=color
        if lower:
            coords=sorted(c for r,c in lower)
            rr=0
            for c in coords:
                out[rr][c]=color
    return out
