    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for a, b in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                    if 0 <= a < h and 0 <= b < w and grid[a][b] == color and (a, b) not in seen:
                        seen.add((a, b))
                        stack.append((a, b))
            components.append((color, cells))

    quadrants = {"UL": [], "UR": [], "LL": [], "LR": []}
    for color, cells in components:
        r0 = min(r for r, c in cells)
        c0 = min(c for r, c in cells)
        q = ("U" if r0 < h // 2 else "L") + ("L" if c0 < w // 2 else "R")
        quadrants[q].append((color, cells))

    out = [[0] * w for _ in range(h)]

    def place(item, top, left):
        color, cells = item
        r0 = min(r for r, c in cells)
        c0 = min(c for r, c in cells)
        for r, c in cells:
            rr, cc = top + r - r0, left + c - c0
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color

    # The diagonal upper-left/lower-right color pair is stacked in the left lane.
    for color, cells in quadrants["UL"]:
        height = max(r for r, c in cells) - min(r for r, c in cells) + 1
        place((color, cells), h - height, 0)
    for color, cells in quadrants["LR"]:
        place((color, cells), 4, 0)

    # The upper-right/lower-left pair occupies the right lane. The wider
    # component uses the bottom slot; ties put the upper-right object there.
    right_items = [("UR", item) for item in quadrants["UR"]] + [("LL", item) for item in quadrants["LL"]]
    if len(right_items) == 2:
        def width(entry):
            cells = entry[1][1]
            return max(c for r, c in cells) - min(c for r, c in cells) + 1
        a, b = right_items
        bottom_idx = 0 if width(a) >= width(b) else 1
        for i, (quad, item) in enumerate(right_items):
            height = max(r for r, c in item[1]) - min(r for r, c in item[1]) + 1
            if i == bottom_idx:
                place(item, h - height, w // 2)
            else:
