            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for a, b in ((x+1,y), (x-1,y), (x,y+1), (x,y-1)):
                    if 0 <= a < h and 0 <= b < w and grid[a][b] == color and (a,b) not in seen:
                        seen.add((a,b))
                        stack.append((a,b))
            comps.append((color, cells))

    by_color = {}
    for color, cells in comps:
        by_color.setdefault(color, []).append(cells)

    # The color whose leftmost component lies farther left occupies the left lane.
    def left_edge(color):
        return min(min(c for r,c in cells) for cells in by_color[color])
    colors = sorted(by_color, key=left_edge)
    left_color, right_color = colors[0], colors[1]
    left_parts = by_color[left_color]
    right_parts = by_color[right_color]

    def xcenter(cells):
        return sum(c for r,c in cells) / len(cells)
    # Within each color, the leftmost motif is placed at the bottom, the other above.
    left_parts.sort(key=xcenter)
    right_parts.sort(key=xcenter)

    def box(cells):
        return (min(r for r,c in cells), max(r for r,c in cells),
                min(c for r,c in cells), max(c for r,c in cells))

    left_width = max(box(cells)[3] - box(cells)[2] + 1 for cells in left_parts)
    right_start = left_width + 1
    out = [[0] * w for _ in range(h)]

    def place(color, cells, top, left):
